"""Build offline Codex and illustrated report from current contracts and proofs.
PNG images are embedded byte-for-byte; no image generation or screenshot editing."""
from pathlib import Path
import json,base64,html,hashlib,re
R=Path(__file__).resolve().parent.parent
J=lambda p:json.loads((R/p).read_text())
e=lambda s:html.escape(str(s))
C=J('report/CONTRATS_LEVEL_DESIGN_V109.json');B=J('report/browser-results-v109.json');D=J('report/operation-drive-v109.json');L=J('report/logistics-drive-v109.json');P=J('report/pursuit-drive-v109.json');PROV=J('baseline/SOURCES_PRESERVEES_V108.json')
passed=int(re.search(r'^# pass (\d+)$',(R/'report/node-tests-v109.tap').read_text(),re.M).group(1))
assert passed==260 and all(t['ok'] for t in B['tests']) and not B['pageErrors'] and not B['consoleErrors']
assert hashlib.sha256((R/'JOUER_ALIENS_V109.html').read_bytes()).hexdigest()==B['htmlSha256']
STYLE='''*{box-sizing:border-box}html{scroll-behavior:smooth;color-scheme:dark}body{margin:0;background:#0b1514;color:#d4dfd1;font:16px/1.8 Arial,Helvetica,sans-serif}main{max-width:1160px;padding:42px 32px 84px;margin:auto}a{color:#cee1b3;text-underline-offset:4px}h1{font:400 clamp(36px,5vw,63px)/1.13 Georgia,serif;letter-spacing:-.025em;color:#e1e9d8;margin:20px 0 24px}h2{font:400 29px/1.3 Georgia,serif;color:#cadcba;margin:44px 0 18px;padding-top:26px;border-top:1px solid #405d4d}h3{font-size:20px;line-height:1.35;font-weight:500;color:#d1dcc6;margin:26px 0 10px}p{max-width:96ch}.eyebrow{font:11px/1.45 monospace;letter-spacing:.25em;color:#9baea6;text-transform:uppercase}.lead{font-size:20px;line-height:1.65;max-width:940px}.callout{padding:18px 24px;margin:27px 0;background:#1d342b;border-left:3px solid #b6a674;color:#d0d9bc}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.metric{padding:20px;border:1px solid #3a564a;background:linear-gradient(135deg,#203931,#11231d)}.metric strong{font:400 33px/1.2 Georgia,serif;color:#e0d9ad;display:block}.metric small{font-size:12px;color:#adc3b0}nav{display:flex;flex-wrap:wrap;gap:16px 25px;border-bottom:1px solid #334c3e;padding:12px 0 20px}table{width:100%;border-collapse:collapse;margin:22px 0;font-size:12px;line-height:1.5}th,td{text-align:left;vertical-align:top;padding:11px 13px;border:1px solid #3e594b}th{background:#263e32;font-weight:600;color:#dfdfc4}tr:nth-child(even){background:#192d2570}.small,figcaption{font-size:13px;line-height:1.65;color:#a7b8a4}figure{margin:30px 0 42px}img{width:100%;height:auto;display:block;background:#07120e;border:1px solid #536a55}figcaption{margin-top:10px}code,pre,.mono{font:12px/1.6 ui-monospace,Consolas,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#07120e;border:1px solid #3d5846;padding:20px}.room{padding:28px;margin:28px 0;border:1px solid #3d5b4a;background:linear-gradient(145deg,#172b2370,#0c1a1480)}.room.new{border-color:#577f86;background:linear-gradient(140deg,#17313a80,#101d1b80)}.room h2{padding-top:0;border:none;margin-top:12px}.diagram{display:block;width:100%;height:auto;background:#0a1b15;border:1px solid #3c5e4c;margin:20px 0}details{margin:15px 0;padding:17px 20px;border:1px solid #385246;background:#13271d}summary{cursor:pointer;color:#d3ddbc;font-size:17px;line-height:1.4}.room summary{font-size:14px}input{width:100%;padding:16px 19px;border:1px solid #738975;background:#13271f;color:#e0e8d9;font:15px Arial}input:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #d5ddb3;outline-offset:4px}.hidden{display:none!important}.chip{display:inline-block;margin:2px 6px 2px 0;padding:4px 9px;border:1px solid #526952;background:#294134;color:#d1daba;font:11px/1.4 monospace}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.rule-index{color:#789284;font:12px monospace;margin-right:10px}@media(max-width:740px){main{padding:25px 16px}.metrics{grid-template-columns:1fr 1fr}.room{padding:15px}.two{grid-template-columns:1fr}table{display:block;overflow-x:auto}.lead{font-size:17px}h2{font-size:25px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#222}h1,h2,h3{color:#222}main{padding:0}.room,figure,tr{break-inside:avoid}nav,input{display:none}.room{break-before:page}img{max-height:160mm;object-fit:contain}.callout{background:#f4f4ef;color:#222}}'''
def page(title,body,script=''):
 return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Aliens V109 : branche jouable, données de niveau et preuves locales"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{body}</main>{script}</body></html>'
def table(headers,rows):
 return '<table><thead><tr>'+''.join('<th>'+e(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def metrics(rows):return '<div class="metrics">'+''.join('<div class="metric"><strong>'+e(v)+'</strong><small>'+e(t)+'</small></div>' for v,t in rows)+'</div>'
def picture(c,title):
 raw=(R/'report/captures-v109'/c['file']).read_bytes();assert raw[:8]==b'\x89PNG\r\n\x1a\n'
 return f'<figure id="capture-{e(c["file"].split("_")[0])}"><h3>{e(title)}</h3><img loading="lazy" src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{e(title)} — capture du module V109"><figcaption><strong>{e(c["file"])}</strong> — {e(c["origin"])}. PNG brut de Chromium ; aucune retouche, aucune génération d’image. Branche autonome, pas le build natif Tantalus.</figcaption></figure>'
def diagram(room):
 w,d=room['width'],room['depth'];out=[f'<svg class="diagram" viewBox="-25 -30 {w+50} {d+115}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Plan de géométrie {e(room["title"])}"><rect width="{w}" height="{d}" fill="#142c23" stroke="#67856d"/>']
 for b in room['solids']:
  fill='#729fa5' if b.get('material')=='glass' else '#566c5b';out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{fill}" stroke="#a0b4a0" fill-opacity=".6"/><text x="{b["x"]+3}" y="{b["z"]+13}" fill="#e2ead1" font-size="10">{e(b["id"])}</text>')
 for b in room['doors']+room['hatches']:
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b3934944" stroke="#e5c779" stroke-width="2" stroke-dasharray="4 3"/>')
 for prop in room['props']:out.append(f'<circle cx="{prop["x"]}" cy="{prop["z"]}" r="5" fill="#b5cba0"/>')
 for x in room['exits']:
  out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="12" fill="none" stroke="#a4d5b0" stroke-width="3"/><line x1="{x["x"]}" y1="{x["z"]}" x2="{x["arrival"]["x"]}" y2="{x["arrival"]["z"]}" stroke="#b1c797" stroke-dasharray="4 5"/><circle cx="{x["arrival"]["x"]}" cy="{x["arrival"]["z"]}" r="5" fill="#dadbb5"/>')
 for r in [x for x in C['resources']+C['alarms'] if x['roomId']==room['id']]:
  out.append(f'<circle cx="{r["x"]}" cy="{r["z"]}" r="{r["reach"]}" fill="none" stroke="#e4cb76" stroke-dasharray="3 5"/><text x="{r["x"]-30}" y="{r["z"]-29}" fill="#f0d586" font-size="11">{e(r["id"])}</text>')
  if r.get('emitter'):out.append(f'<circle cx="{r["emitter"]["x"]}" cy="{r["emitter"]["z"]}" r="6" fill="#e09361"/>')
 out.append(f'<text x="8" y="{d+27}" fill="#c4cdb6" font-size="13">Schéma issu des données — pleins : collisions · ambre : portes/sas · cercle pointillé : portée de travail</text><text x="8" y="{d+53}" fill="#97b39e" font-size="12">Ce plan de conception n’est pas une capture du rendu. La carte en jeu ne montre ni ennemis ni stocks cachés.</text></svg>');return ''.join(out)
RULES=[
('Deux lieux, un détour réellement facultatif','La galerie et la réserve créent la boucle Operations → Galerie logistique → Réserve technique → Maintenance. Les cinq objectifs ordonnés de Repli sur Operations restent inchangés. La liaison médicale de service et la route directe restent praticables. La reconnaissance du détour est un bilan local : elle ne remplace aucune mission historique.'),
('Un stock est un objet du niveau','Chaque réserve a un identifiant, une emprise métallique au sol, un point de travail, une portée et une quantité finie. La desserte bloque corps et balles. L’interaction ignore uniquement son propre support dans le rayon de travail, jamais les cloisons ou les autres meubles. Les scellés prennent 1,05 seconde à ouvrir ; les réserves ne sont créditées qu’au bout du geste.'),
('Conservation exacte des ressources','Les trois stocks apportent trois lots personnels, deux trousses et une cartouche pour sentinelle. Inventaire restant + ressources dépensées doit toujours correspondre à la somme des stocks effectivement ouverts. Aucun objet n’est gagné à l’entrée d’une pièce, à l’inspection suivante ou au chargement. Une caisse déjà récupérée reste ouverte et vide.'),
('Soigner un acteur présent','Le soin dure 1,6 seconde, exige un allié vivant et proche, et rend au maximum 30 PV, sans dépasser 100. Il consomme une trousse seulement à son achèvement. Newt peut être soignée une fois recrutée ; elle ne reçoit pas d’arme. Aucun soin ne ressuscite un acteur, ne répare une tourelle ou ne cible un équipier dans une autre pièce.'),
('Ravitailler ne signifie pas recharger gratuitement','Un lot personnel donne 18 cartouches en 0,85 seconde, avec plafond de 96. Une cartouche de sentinelle ajoute 40 coups en 1,35 seconde, plafond de 120. Le transfert n’a lieu que si un manque existe et si l’objet de réserve correspondant est réellement disponible. La sentinelle conserve ses tirs à ligne dégagée et n’a aucun rechargement automatique.'),
('Le travail reste exposé','Marcher, tirer, quitter la portée, subir un impact ou changer les données de la cible interrompt le geste. Le joueur et la cible ne doivent pas se déplacer ou tirer pendant l’assistance ; seul l’allié aidé est momentanément immobilisé, pas le reste de l’escouade. Un nouvel ordre à cet allié annule le soin. Les contacts continuent de simuler leurs attaques ; la pause seule suspend globalement le temps.'),
('Reprendre au milieu d’un soin','L’export contient durée, temps effectué, positions de départ, santé et munitions observées. L’import vérifie ces données contre l’état physique restauré et reprend en pause. Un fichier ne peut pas revendiquer une cible absente, modifier une durée, accorder des ressources inexpliquées ou soigner pendant le chargement. L’action interrompue ne consomme pas sa trousse.'),
('Une sirène attire, elle ne crée pas de menace','La commande de diagnostic demande 0,65 seconde, émet pendant 8 secondes et impose un délai total de 20 secondes avant réactivation. Les impulsions suivent le système sonore V108 : chemins libres, atténuation aux passages et limite de deux liaisons. Aucun Xéno n’est créé, tué ou téléporté par le diagnostic. Les contacts encore vivants peuvent chercher le dernier son et entrer par un seuil réellement accessible.'),
('Placer correctement la source sonore','Le point de commande peut appartenir au meuble ; l’émetteur de son doit être hors de son volume obstrué. Dans la réserve, la commande est à (1214, 238), l’émetteur à (1170, 238). Un émetteur enfoui dans le cabinet empêchait initialement la propagation par chemin : la géométrie a été corrigée, pas le filtre acoustique contourné.'),
('Fermer derrière l’équipe a une conséquence','Les huit liaisons sont réciproques et instancient seize volumes de seuil. Leur fermeture coupe corps, vue, tirs et trajets sonores. Un acteur présent ou en transit interdit l’écrasement du seuil. Les nouveaux raccords ne bénéficient d’aucune exemption : les trois Marines, Newt et les créatures doivent atteindre leur accès et attendre une arrivée libre.'),
('Conserver la menace et les pertes','Onze ennemis et une sentinelle existent dans le catalogue ; dix ennemis sont dans le réseau de l’opération, le Sulaco reste isolé en inspection. Une créature qui traverse conserve identité et vie. Quitter une pièce ne retire pas un ennemi de la condition de défense. Les blessures et munitions suivent le même registre d’équipe à travers les sept lieux.'),
('Respecter le vocabulaire des lieux','La galerie utilise métal bleuté, rideau de fret, palettes, tracteur stationné et portiques. La réserve utilise comptoir médical, casiers, batteries et diagnostic ambre. Leur plan ne doit pas être copié sans fonction : le passage central ouvre une ligne de tir, les grandes masses offrent un contournement et les stocks sont placés après l’exposition, pas sur le point d’arrivée.'),
('Un appui graphique doit correspondre à un appui physique','Le tracteur est ancré au volume parked-tug, sans dessin posé artificiellement au-dessus d’une autre caisse. Les chariots de secours et de munitions utilisent leur bodyId. Le moniteur de réserve et la caisse sur palette ont une élévation explicite reliée à leur support. Les objets proches ne dérivent pas avec la caméra ; la parallaxe est réservée aux éléments lointains.'),
('Rendre lisible sans cacher le combat','La silhouette, les pieds, le volume de tir et l’emprise au sol utilisent les mêmes coordonnées. Les premiers plans proches sont atténués s’ils cachent un allié, mais conservent leurs collisions. Les scellés ouverts montrent un couvercle et un contenu vide ; la sirène montre un cycle puis un délai. Les textures et personnages sont encore procéduraux, pas des sprites finalisés.'),
('HUD et carte hors du terrain','Santé, munitions, détecteur, ressources et ordres restent dans des bandes hors canvas. La carte et les archives remplacent temporairement le terrain. La carte ne dévoile que les lieux visités : ni positions ennemies, ni santé adverse, ni réserves non découvertes. Les contrôles 844 × 390 et 390 × 844 sont émulés ; aucun appareil physique n’est certifié.'),
('Migrer sans transformer l’ancien parcours','V108 est validée par son propre importeur avant migration. Les pièces et membres hérités gardent vies, ressources, ordres et progression. Les deux lieux supplémentaires sont initialisés au temps courant, les nouveaux contacts sont sans mémoire et les nouvelles liaisons sont ouvertes. Aucune réserve n’est offerte. V107 et V106 passent par leurs validateurs antérieurs ; V106 reste une inspection.'),
('Définition d’un lieu prêt à raccorder','Vérifier tous les seuils avec le gabarit du groupe, tirer contre chaque volume, contourner les props, interrompre une assistance, revenir après collecte, importer à mi-geste, déclencher la sirène portes ouvertes puis isolées, et terminer le repli. Les graphismes seuls ne prouvent ni la géométrie ni le raccord natif. La fusion au moteur Tantalus doit être testée sur ses sources exactes.'),
]
notes={
'v109-logistics':('QUAI / NOUVEAU','Galerie sous scellés','Le rideau coupe le couloir central. Le tracteur stationné occupe son vrai gabarit au nord et la palette laisse un passage par le sud. La réserve de munitions est au-delà du contact du quai : l’approche doit être nettoyée ou couverte avant les 1,05 seconde de travail.'),
'v109-reserve':('SECOURS / NOUVEAU','Choisir le bon moment','Le premier berceau contient la cartouche de sentinelle ; les trousses sont derrière la cloison. La sirène se trouve côté maintenance pour offrir une option de détour, mais l’accès nord ouvert permet aussi l’arrivée d’un contact. La portée de commande et le point émetteur sont distincts.'),
'v107-operations':('CARREFOUR','Une branche de plus, pas un radar','L’accès sud mène maintenant à la galerie. Le meuble central conserve son rôle de couverture et de coupure visuelle. Un groupe doit encore rejoindre le seuil : Rallier ne téléporte personne. L’accès à la logistique ne modifie pas les conditions de Newt ni de défense.'),
'v107-service':('MAINTENANCE','Le relais au bout de la boucle','La réserve rejoint la maintenance par le nord. Aucun obstacle hérité n’a été déplacé pour inventer un raccord ; l’arrivée libre est vérifiée contre la pompe et le transformateur. La commande du relais garde son rôle de jalon local, sans devenir un réseau électrique général.'),
'v106-hadley':('INSERTION','Départ conservé','Porte résidentielle, contacts et raccord Operations sont conservés. Les stocks commencent à zéro. Les créatures peuvent suivre le groupe après le départ si elles possèdent un indice et une route ouverte.'),
'v106-medlab':('ESCORTE','Secourir avant d’assister','Le vitrage laisse voir sans autoriser les tirs au travers. Newt reste protégée avant recrutement, puis doit rejoindre le groupe. Une trousse peut la soigner à portée ; le ravitaillement ne peut jamais lui donner de cartouches.'),
'v106-sentry':('DÉFENSE','Quarante coups, pas une réserve infinie','La cartouche de réserve se transfère à proximité de la sentinelle vivante. Il faut trouver une fenêtre de 1,35 seconde sans déplacement de cible ni variation de ses munitions. Un tir de la sentinelle pendant le geste l’interrompt ; son ravitaillement est une action protégée, pas un bouton instantané au milieu de la rafale.'),
'v106-sulaco':('INSPECTION','Final natif préservé','Cette pièce reste inspectable seule. Elle n’est pas raccordée à Repli sur Operations. La représentation de la Reine et du loader n’est pas un nouveau final filmique ; la commande du sas reste réservée au système historique non fusionné ici.')}
# Codex
body='<p class="eyebrow">ALIENS / TANTALUS — carnet de conception V109</p><h1>Des réserves limitées.<br>Un détour sous pression.</h1><p class="lead">Une boucle de fret et de maintenance prolonge le parcours. Les ressources, les gestes et les trajets sonores partagent le même monde physique.</p>'
body+=metrics([('8','lieux inspectables'),('7','lieux reliés'),('3','stocks finis'),('2','nouvelles pièces')])
body+='<div class="callout">Ce Codex décrit la branche autonome livrée et ses données exécutées. Il ne certifie pas les 64 salles du moteur Tantalus natif. Les schémas sont des plans de conception ; les véritables captures du jeu sont dans le rapport illustré.</div><nav><a href="#doctrine">Contrats</a><a href="#catalogue">Fiches de lieux</a><a href="JOUER_ALIENS_V109.html">Jouer</a><a href="RAPPORT_ILLUSTRE_V109.html">Voir les captures</a></nav><h2 id="doctrine">Contrats de level design</h2>'
md=['# CODEX LEVEL DESIGN — ALIENS V109 / Logistique sous pression','Version 109.0.0-rc.1. Huit lieux inspectables, sept connectés ; deux nouveaux lieux. Branche autonome, aucune fusion des 64 salles natives.']
for i,(title,text) in enumerate(RULES,1):
 body+=f'<details><summary><span class="rule-index">{i:02}</span>{e(title)}</summary><p>{e(text)}</p></details>';md+=['## '+title,text]
body+='<h2>Valeurs d’action et de réserve</h2>'+table(['Action','Durée','Effet à la fin','Plafond / contrainte'],[['Scellés','1,05 s','Contenu attribué une seule fois','3 lots / 2 trousses / 1 cartouche au total'],['Soin','1,6 s','+30 PV maximum','100 PV ; vivant et à portée'],['Ravitaillement personnel','0,85 s','+18 cartouches','96 ; pas Newt'],['Sentinelle','1,35 s','+40 coups','120 ; tourelle vivante immobile'],['Diagnostic','0,65 s','Son 8 s','Réactivation après 20 s ; aucun spawn']])
body+='<h2 id="catalogue">Plans et fiches de lieux</h2><input id="filter" type="search" placeholder="Rechercher un lieu, un support ou une réserve…" aria-label="Filtrer les lieux"><p id="filter-note" class="small">8 lieux — coordonnées issues du catalogue exécuté</p>'
ordered=sorted(C['rooms'],key=lambda r:list(notes).index(r['id']))
for room in ordered:
 label,title,text=notes[room['id']];new=room['id'].startswith('v109');stock=[x for x in C['resources'] if x['roomId']==room['id']];alarms=[x for x in C['alarms'] if x['roomId']==room['id']]
 body+=f'<article class="room{" new" if new else ""}" data-search="{e(json.dumps([room,stock,alarms],ensure_ascii=False).lower())}"><p class="eyebrow">{e(label)} / {e(room["id"])} / {e(room["mode"])}</p><h2>{e(room["title"])}</h2><p>{e(room["subtitle"])}</p><h3>{e(title)}</h3><p>{e(text)}</p>'+diagram(room)
 body+=table(['Destination','Seuil x,z','Arrivée locale','Liaison partagée'],[[x['label'],f'{x["x"]}, {x["z"]}',f'{x["arrival"]["x"]}, {x["arrival"]["z"]}',x['linkId']] for x in room['exits']]) if room['exits'] else '<p class="small">Inspection isolée ; aucun raccord de campagne.</p>'
 if stock:body+=table(['Réserve','Point x,z / portée','Emprise','Quantité unique'],[[x['name'],f'{x["x"]},{x["z"]} / {x["reach"]}',x['bodyId'],str(x['grant'])] for x in stock])
 if alarms:body+=table(['Commande','Point de commande','Émetteur libre','Portée'],[[x['name'],f'{x["x"]},{x["z"]}',f'{x["emitter"]["x"]},{x["emitter"]["z"]}',x['reach']] for x in alarms])
 body+='<details><summary>Volumes de collision</summary>'+table(['Volume','x / z','w / d / h','Matériau'],[[b['id'],f'{b["x"]}/{b["z"]}',f'{b["w"]}/{b["d"]}/{b.get("h","—")}',b.get('material','structure')] for b in room['solids']+room['doors']+room['hatches']])+'</details><details><summary>Appuis et objets de décor</summary>'+table(['Équipement','Support nommé','Référence physique','Élévation'],[[p['type']+' / '+p['id'],p.get('support','—'),p.get('bodyId',p.get('supportId','mur / sol')),p.get('elevation',0)] for p in room['props']])+'</details><p class="small">Recette : circuler des deux côtés, tirer contre les emprises, observer le seuil occupé, reprendre à mi-action et revenir sans réinitialiser les réserves. Conserver la pause globale et les acteurs uniques.</p></article>'
 md+=['## '+room['title'],room['subtitle'],title+' — '+text,'### Liaisons']+[f'- {x["label"]} : seuil ({x["x"]},{x["z"]}), arrivée ({x["arrival"]["x"]},{x["arrival"]["z"]}), {x["linkId"]}.' for x in room['exits']]
 md+=['### Volumes']+[f'- {b["id"]} : x={b["x"]}, z={b["z"]}, w={b["w"]}, d={b["d"]}, h={b.get("h","—")}.' for b in room['solids']+room['doors']+room['hatches']]
 md+=['### Appuis']+[f'- {p["id"]} : {p.get("support","—")}, référence={p.get("bodyId",p.get("supportId","mur/sol"))}, élévation={p.get("elevation",0)}.' for p in room['props']]
 if stock:md+=['### Stocks finis']+[json.dumps(x,ensure_ascii=False) for x in stock]
 if alarms:md+=['### Diagnostic acoustique']+[json.dumps(x,ensure_ascii=False) for x in alarms]
body+='<h2>Contrat et portée de validation</h2><p class="mono">Version '+e(C['version'])+' · empreinte '+e(C['contract'])+'</p><p>47 emprises fixes, 9 portes intérieures, 16 volumes de seuil et 42 instances de décor nommées. Ces nombres ne sont pas des comptes de sprites uniques. Une modification des coordonnées exige une validation et une migration de contrat ; ne pas corriger une collision uniquement dans le renderer.</p>'
filter_js='''<script>const f=document.querySelector('#filter'),cards=[...document.querySelectorAll('.room')];f.addEventListener('input',()=>{const q=f.value.toLocaleLowerCase('fr').trim();let n=0;for(const c of cards){const yes=c.dataset.search.includes(q);c.classList.toggle('hidden',!yes);if(yes)n++;}document.querySelector('#filter-note').textContent=n+' lieu(x) correspondant(s)';});</script>'''
(R/'CODEX_LEVEL_DESIGN_V109.html').write_text(page('Aliens V109 — Codex de la logistique',body,filter_js));(R/'CODEX_LEVEL_DESIGN_V109.md').write_text('\n\n'.join(md)+'\n')
# Report: 12 highlighted actual captures, every other raw capture remains in evidence directory.
selection=[('00_menu.png','Une opération conservée, huit inspections'),('16_galerie_entree.png','Nouvelle galerie : rejoindre le quai'),('17_galerie_stock_ouvert.png','Les scellés sont ouverts ; la réserve est finie'),('18_soin_action_reelle.png','Un soin commencé dans le navigateur'),('19_reserve_apres_soin.png','Réserve technique : le soin a consommé sa trousse'),('20_sirene_diagnostic.png','La sirène alerte le réseau existant'),('21_sentinel_ravitaillement.png','Une cartouche de terrain pour la sentinelle'),('22_carte_boucle_service.png','Une vraie boucle, sans carte radar'),('23_bilan_logistique.png','Retour avec les ressources restantes'),('10_contact_poursuite.png','La poursuite entre pièces reste active'),('12_sas_isole.png','Isoler un raccord conserve son rôle'),('24_logistique_844x390.png','HUD et logistique hors canvas à 844 × 390')]
byfile={c['file']:c for c in B['captures']};body='<p class="eyebrow">ALIENS / V109 — rapport de livraison local</p><h1>Logistique sous pression</h1><p class="lead">Deux lieux supplémentaires, des réserves finies et des actions exposées prolongent la poursuite persistante. Le détour sert le jeu ; il ne remplace pas la campagne native.</p>'+metrics([('260','tests Node réussis'),('103','contrôles navigateur'),('4','opérations locales terminées'),('25','PNG directs de Chromium')])
body+='<nav><a href="JOUER_ALIENS_V109.html">Jouer</a><a href="CODEX_LEVEL_DESIGN_V109.html">Codex</a><a href="#preuves">Preuves</a><a href="#limites">Limites</a></nav><div class="callout">Douze captures mises en avant ci-dessous, extraites sans retouche des 25 PNG du dossier de recette. Le HTML livré a été exécuté dans Chromium avec son chargeur Blob normal. Les points repris sont des exports non modifiés des parcours automatisés ; les gestes indiqués sont effectués avec la véritable interface.</div>'
body+='<h2>Un prolongement jouable</h2><p>Operations donne accès à la galerie de fret, puis à la réserve technique et au relais de maintenance. Les anciens itinéraires sont conservés. Les trois stocks apportent 3 lots personnels, 2 trousses et 1 cartouche de sentinelle : on choisit quand les dépenser et qui assister. Les deux nouveaux Xénos appartiennent au catalogue fixe. La sirène utilise leurs chemins et ceux des contacts déjà présents, sans créer de vague.</p><p>L’action de terrain exige proximité, immobilité et passage dégagé. Les soins peuvent être interrompus par un tir, un impact ou un déplacement. Le jeu conserve les mêmes portes, attaques, munitions et mémoires pendant ce travail. Le chargeur, la santé et les ressources ne sont jamais réinitialisés lors d’un transfert.</p>'
for file,title in selection:body+=picture(byfile[file],title)
body+='<h2 id="preuves">Ce que les contrôles prouvent</h2>'+table(['Recette','Résultat','Portée'],[['Node','260 / 260','180 tests hérités + 80 V109 ; états préparés pour des invariants ciblés'],['Navigateur','103 / 103','64 contrôles précédents rejoués + 39 nouveaux ; six contextes'],['Opérations','4 / 4','Deux anciens itinéraires + boucle logistique avec/sans rechargements'],['Poursuite distincte','2 passages ennemis','Parcours initial, fuite, mesure, défense et sas'],['Captures','25 PNG','Douze mises en avant ; toutes les provenances dans browser-results-v109.json']])
body+='<p>Les pilotes complets utilisent mouvement, tir, interaction, ordres et progression du temps. Ils lisent l’état pour planifier le trajet ; ils ne réécrivent ni positions, vies, chargeurs, portes, ressources ou objectifs. Dans la boucle logistique, la blessure utilisée pour tester le soin provient d’une vraie attaque. Le second trajet recharge les exports, y compris au milieu du soin et du ravitaillement de la sentinelle.</p>'
rows=[]
for v in D['results']+L['results']:
 team=v.get('team',v.get('ammunition'));rip=next(a for a in team if a['id']=='ripley');rows.append([v['variant'],'terminé' if v['complete'] else 'échec',v['transfers'],v['inputs'],f'{v["elapsed"]:.2f}',f'{rip["hp"]} PV / {rip["ammo"]} cartouches'])
body+=table(['Parcours','État','Transferts équipe','Entrées / sous-pas','Secondes simulées','Ripley finale'],rows)+'<p class="small">Les secondes de simulation et les entrées du pilote ne sont pas une estimation de durée pour un joueur humain. Les rechargements ne restaurent pas les réserves. Dans les deux boucles, une trousse, un lot personnel et la cartouche de sentinelle sont dépensés ; il reste 2 lots et 1 trousse.</p>'
body+='<h2>Corrections trouvées pendant la recette</h2><p>Les commandes logistiques produisent de nouveaux types de bruit : ils ont été ajoutés explicitement au validateur de sauvegarde, sans accepter des champs arbitraires. Le point sonore de la sirène a été déplacé hors du meuble pour que le calcul de chemin acoustique puisse réellement partir de l’émetteur. Les ressources et le tracteur ont des volumes physiques dédiés et un dessin ancré à leur face avant, plutôt qu’un meuble qui ne serait qu’une image.</p>'
body+='<h2 id="limites">Limites de cette version</h2><p>Branche autonome V108 poursuivie, aucune fusion dans les 64 salles Tantalus ni publication GitHub/Vercel. Les transferts entre pièces restent discrets par seuil ; les tirs restent dans la pièce courante. Le réseau sonore est une règle tactique, pas une simulation acoustique de studio. Le renderer et les personnages restent procéduraux stylisés ; pas de nouveaux sprites finalisés, de doublage, de manette certifiée, de multijoueur ni de nouveau final Reine/P-5000/sas. Les viewports tactiles sont émulés, pas des appareils physiques.</p><p>Les sauvegardes sont validées structurellement et comptablement ; ce n’est pas une signature anti-triche. L’inventaire de terrain est commun au groupe, pas un système complet d’encombrement par Marine. Les durées de travail n’utilisent pas encore d’animations artistiques dédiées.</p>'
body+='<h2>Sources de la livraison</h2><p class="mono">Base : '+e(PROV['archive'])+'<br>SHA-256 : '+e(PROV['sha256'])+'<br>HTML soumis au navigateur : '+e(B['htmlSha256'])+'<br>Contrat : '+e(C['contract'])+'</p><p>Treize sources/tests hérités sont comparés octet pour octet à la V108. Les fichiers de preuve nommés v108 et les états historiques restent des références de migration, pas des résultats revendiqués pour cette livraison. Les preuves courantes portent le suffixe v109.</p>'
(R/'RAPPORT_ILLUSTRE_V109.html').write_text(page('Aliens V109 — Rapport illustré',body))
